 [6468]={["acquisitionConfidence"]="reported",["acquisitionKind"]="Quest reward: Leatherworking pattern",["acquisitionLocation"]={["quality"]="classic-reference",["spot"]="Upper cave above Wailing Caverns: Ebru (Deviate Eradication)",["x"]=45.97,["y"]=36.34,["zone"]="The Barrens"},["acquisitionLocationConfidence"]="classic-reference",["armorType"]="Leather",["availableLevel"]=18,["bindingEvidence"]="forever-client-item-tooltip",["bindingEvidenceURL"]="https://theforeverera.com/en/recipes/leatherworking/deviate-scale-belt/",["bindingStatus"]="boe",["confidence"]="client",["instructions"]="Take Deviate Eradication from Ebru in the upper cave above Wailing Caverns. Complete the dungeon quest (7 each: Deviate Ravagers, Vipers, Shamblers and Dreadfangs), then CHOOSE Pattern: Deviate Scale Belt as your reward. Sizzle Stick and Dagmire Gauntlets are mutually exclusive alternatives. The belt's Leatherworking learning requirement is not independently established. The map pin is a Classic-reference approach point for Ebru's upper cave; confirm in Forever. The finished belt is bind-on-equip and can also be obtained through another crafter.",["itemID"]=6468,["itemSourceEvidence"]="reported",["name"]="Deviate Scale Belt",["notes"]="+6 Stamina, +5 Agility, +3 Strength. BoE leatherworking piece; The quest-cache reward is documented in Forever; location remains a Classic reference.",["profession"]="Leatherworking",["professionSkillRequired"]=90,["reagents"]={[1]={["amount"]=10,["itemID"]=6471,["name"]="Perfect Deviate Scale"},[2]={["amount"]=10,["itemID"]=6470,["name"]="Deviate Scale"},[3]={["amount"]=2,["itemID"]=2321,["name"]="Fine Thread"}},["recipeLearnMethod"]="pattern",["recipeLearnSkillEvidence"]="explicit-forever-pattern-item",["recipeMethodCaution"]="Pattern: Deviate Scale Belt; Forever client/quest listing links Deviate Eradication.",["recipeMethodEvidence"]="forever-client-index; live acquisition not certified",["recipeMethodEvidenceURL"]="https://questing.wiki/wow-forever/professions/leatherworking/",["recipeRequirementEvidenceURL"]="https://theforeverera.com/en/recipes/leatherworking/deviate-scale-belt/",["slot"]="Waist",["source"]="Pattern: Deviate Scale Belt - Deviate Eradication quest reward",["sourceType"]="Leatherworking",["sourceURL"]="https://foreverdb.net/item/6468",["statRole"]="physical",["zone"]="Wailing Caverns / The Barrens"},
